package com.app.pverse.dto.response;

import com.app.pverse.entity.UserSettings.Language;
import com.app.pverse.entity.UserSettings.Theme;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class UserSettingsDto {
    private Long id;
    private Long userId;
    private Theme theme;
    private Language language;
    private Boolean notificationsEnabled;
    private String extendedSettings;
}

-- Kiểm tra database
USE pverse_db;

-- Đếm users
SELECT COUNT(*) as total_users FROM users;

-- Đếm settings
SELECT COUNT(*) as total_settings FROM user_settings;

-- Kiểm tra user có settings không
SELECT 
    u.id as user_id,
    u.username,
    us.id as settings_id,
    us.theme,
    us.language
FROM users u 
LEFT JOIN user_settings us ON u.id = us.user_id
LIMIT 5;

-- Kiểm tra user ID = 1
SELECT * FROM users WHERE id = 1;
SELECT * FROM user_settings WHERE user_id = 1;
